import fs from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test.describe("upload vendor documents", () => {
  test("extraction completes in the background", { tag: "@DOC-02" }, async ({ apiAs }) => {
    // Arrange: a vendor in draft status owned by the member's tenant
    const member = await apiAs("member");
    const vendorRes = await member.post("/api/vendors", {
      data: {
        name: uniqueName("Doc Vendor"),
        category: "services",
        contact_email: `doc-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.com`,
      },
    });
    expect(vendorRes.status(), await vendorRes.text()).toBe(201);
    const vendor = await vendorRes.json();
    expect(vendor.status).toBe("draft");

    // Act: upload the insurance certificate
    const uploadRes = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "insurance_certificate",
        file: {
          name: "insurance_certificate.txt",
          mimeType: "text/plain",
          buffer: fs.readFileSync(sample("insurance_certificate.txt")),
        },
      },
    });
    expect(uploadRes.status(), await uploadRes.text()).toBe(201);
    const uploaded = await uploadRes.json();
    expect(uploaded.kind).toBe("insurance_certificate");

    // Assert: processing finishes in the background and the document becomes extracted
    let document: { status: string } = uploaded;
    await expect
      .poll(
        async () => {
          const res = await member.get(`/api/documents/${uploaded.id}`);
          expect(res.status(), await res.text()).toBe(200);
          document = await res.json();
          return document.status;
        },
        { timeout: 60_000, intervals: [500, 1000, 2000] },
      )
      .toBe("extracted");

    const extractionRes = await member.get(`/api/documents/${uploaded.id}/extraction`);
    expect(extractionRes.status(), await extractionRes.text()).toBe(200);
    const extraction = await extractionRes.json();

    expect(Object.keys(extraction.fields).sort()).toEqual(
      expect.arrayContaining(["insurer", "policy_number", "coverage_amount", "expiry_date"]),
    );
    for (const name of ["insurer", "policy_number", "coverage_amount", "expiry_date"]) {
      const field = extraction.fields[name];
      expect(field, `field ${name}`).toBeDefined();
      expect(typeof field.confidence, `confidence of ${name}`).toBe("number");
      expect(field.confidence, `confidence of ${name}`).toBeGreaterThanOrEqual(0);
      expect(field.confidence, `confidence of ${name}`).toBeLessThanOrEqual(1);
    }
  });
});
